css:
.cyan-radio-group {
  font-family: "Rajdhani", "Courier New", monospace;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  padding: 2rem;
  border-radius: 0.5rem;
  max-width: 300px;
}

.cyan-option {
  position: relative;
  display: flex;
  align-items: center;
  cursor: pointer;
  user-select: none;
}

.cyan-radio-input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.cyan-selector {
  position: relative;
  width: 2rem;
  height: 2rem;
  border: 2px solid #00f7ff;
  border-radius: 50%;
  margin-right: 1rem;
  transition: all 0.3s ease;
  box-shadow:
    inset 0 0 1rem rgba(0, 247, 255, 0.2),
    0 0 1rem rgba(0, 247, 255, 0.3);
  background: rgba(5, 10, 20, 0.7);
}

.cyan-selector::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) scale(0);
  width: 1rem;
  height: 1rem;
  border-radius: 50%;
  background: linear-gradient(135deg, #00f7ff, #00a2ff);
  box-shadow: 0 0 1rem rgba(0, 247, 255, 0.8);
  transition: transform 0.3s cubic-bezier(0.68, -0.6, 0.32, 1.6);
  opacity: 0;
}

.cyan-glow {
  position: absolute;
  top: -0.5rem;
  left: -0.5rem;
  right: -0.5rem;
  bottom: -0.5rem;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(0, 247, 255, 0.3), transparent 70%);
  filter: blur(0.5rem);
  opacity: 0;
  transition: opacity 0.3s ease;
  z-index: -1;
}

.cyan-label {
  font-size: 1.2rem;
  font-weight: 600;
  color: #c0c0ff;
  text-transform: uppercase;
  letter-spacing: 0.1rem;
  transition: all 0.3s ease;
  text-shadow: 0 0 0.5rem rgba(100, 0, 255, 0.5);
}

.cyan-connector {
  position: absolute;
  height: 2px;
  width: 0;
  left: 2.5rem;
  background: linear-gradient(90deg, #00f7ff, transparent);
  transition: width 0.3s ease;
}

.cyan-option:hover .cyan-selector {
  transform: scale(1.1);
  box-shadow:
    inset 0 0 1.5rem rgba(0, 247, 255, 0.3),
    0 0 1.5rem rgba(0, 247, 255, 0.5);
}

.cyan-option:hover .cyan-label {
  color: #00f7ff;
  text-shadow: 0 0 1rem rgba(0, 247, 255, 0.8);
}

.cyan-option:hover .cyan-glow {
  opacity: 0.5;
}

.cyan-radio-input:checked + .cyan-selector::before {
  transform: translate(-50%, -50%) scale(1);
  opacity: 1;
}

.cyan-radio-input:checked ~ .cyan-label {
  color: #00f7ff;
  text-shadow: 0 0 1rem rgba(0, 247, 255, 0.8);
}

.cyan-radio-input:checked ~ .cyan-glow {
  opacity: 0.7;
}

.cyan-radio-input:checked ~ .cyan-connector {
  width: 1.5rem;
}

.cyan-option:active .cyan-selector {
  transform: scale(0.95);
}

.cyan-radio-input:checked + .cyan-selector {
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0%,
  100% {
    box-shadow:
      inset 0 0 1rem rgba(0, 247, 255, 0.3),
      0 0 1.5rem rgba(0, 247, 255, 0.5);
  }
  50% {
    box-shadow:
      inset 0 0 1.5rem rgba(0, 247, 255, 0.4),
      0 0 2rem rgba(0, 247, 255, 0.7);
  }
}

.cyan-radio-group:hover .cyan-connector {
  width: 1.5rem;
}
